import json
from pathlib import Path
P=Path(__file__).parent
p=P/'build_data.py';s=p.read_text(encoding='utf-8-sig')
s='\n'.join(line for line in s.splitlines() if "text +=" not in line)
s=s.replace('В 18:20 Ладе предоставлено право публикации.','В 18:20 Ладе впервые предоставлено право публикации.')
s=s.replace('Письменное разрешение Веры получено в 18:24.','Письменное разрешение координатора Веры получено в 18:24.')
s=s.replace('Я запустил задание службы до заморозки','Я работал с настройками задания службы')
s=s.replace("path=[a0,a1,1 if i<7 else 0],event_time={'C05':'18:10','C06':'18:20','C07':'18:15','C08':'18:12','C11':'18:22','C12':'18:24','C28':'17:55','C04':'18:25'}.get(cid,'99:99')", "path=[a0,a1,0 if cid=='C28' or i==7 else 2 if i==8 or cid in ('C01','C09','C10','C15','C16','C19','C20','C21','C23','C24','C26','C27') else 1],event_time={'C02':'18:00','C03':'19:00','C04':'18:25','C05':'18:10','C06':'18:20','C07':'18:15','C08':'18:12','C11':'18:22','C12':'18:24','C13':'18:15','C14':'18:15','C17':'18:15','C18':'18:15','C22':'18:24','C25':'18:22','C28':'17:55'}.get(cid,'99:99')")
p.write_text(s,encoding='utf8')
p=P/'data/narratives.json';items=json.loads(p.read_text(encoding='utf-8-sig'))
extra=[
'К карточке приложена опись, разделяющая документальные записи, свидетельские сообщения и организационные материалы. Такое разделение помогает найти происхождение фразы, но не заменяет её смысловую проверку. Например, дата составления описи не является датой публикации. Секретарь также просит не считать число упоминаний голосованием за версию: длинная переписка может повторять одно сообщение много раз. Если три абзаца восходят к одной записи, перед исследователем остаётся один источник. В учебном наборе это особенно заметно на разрешении координатора, которое процитировано в нескольких местах. Для проверки ответа важнее полнота необходимых условий, чем количество подходящих слов. Итоговая карточка остаётся открытой для уточнений, но в замороженной версии новые сведения не добавляются. Все экспериментальные изменения сохраняются отдельно, чтобы исходное содержание можно было восстановить без обращения к памяти составителя. Читатель получает именно эту зафиксированную версию, а не скрытую авторскую последовательность событий.',
'При передаче выгрузки обсуждалась анонимизация. В учебном тексте оставлены вымышленные имена, потому что они помогают связывать строки разных источников. Реальные пароли, адреса и токены доступа здесь отсутствуют. Сокращение технических полей не означает изменения показанных времён. Администратор просит проверять, относится ли вопрос к учётной записи, действию службы или физическому человеку. Эти три объекта связаны организационно, но для каждого требуются свои доказательства. Если пользователь спрашивает о местонахождении, строка входа может быть тематически близкой, однако недостаточной. Если спрашивает о времени входа, та же строка становится прямым ответом. Поэтому качество контекста нельзя оценивать только числом найденных совпадений. Важна связь записи с проверяемой формулировкой. Эта особенность учитывается при построении пар вопросов, где одинаковые имена встречаются в задачах разных логических типов и требуют разного набора посылок.',
'Памятка к исключению предлагает небольшой мысленный пример, не относящийся к инциденту: если разрешение есть, но включение ключа неизвестно, нельзя подтвердить выполнение всей процедуры. Это пример чтения логического союза, а не дополнительное событие турнира. Редактор помечает его как пояснение, чтобы пример не попал в реестр фактов. В рабочей проверке нормы полезно выписать условия отдельно и указать для каждого источник. Такая таблица не должна содержать восстановленных по привычке значений. Отдельно проверяется граница времени: наличие условия после операции не подтверждает наличие до неё. Публикация может технически состояться и без организационного разрешения, поэтому сам факт выпуска не доказывает соблюдения регламента. Смешение этих уровней создаёт круговой вывод: раз материал появился, значит его разрешили. Досье специально позволяет проверить, избегает ли модель такого рассуждения при кратком ответе со ссылками.',
'В сопроводительной заметке Илья объяснил, почему его рассказ получился длиннее нескольких строк журнала. Человеческое сообщение обычно содержит фон, уточнения и оговорки, тогда как система фиксирует отдельную операцию. Разница длины не означает разницу достоверности сама по себе. Редактор оставил этот фон, чтобы не превратить свидетельство в искусственно идеальный набор ответов. При этом атомарные утверждения выделены отдельно: каждое можно сопоставить с точной цитатой. В свидетельском разделе нет утверждения о том, когда именно задание попало в очередь. Работа с настройками не обязательно равна постановке. Такое разграничение важно после удаления временной записи аудита: рассказ не должен тайно восстанавливать удалённую необходимую посылку. Участник мог заниматься подготовкой, но доступный текст не определяет её точный этап. Ответ о порядке очереди и заморозки должен учитывать именно это ограничение источника.',
'Для сохранения исходного вида письма редактор не расставлял внутри прямой речи дополнительные временные пояснения. Любое уточнение требовало бы нового ответа свидетеля. В исследовательской копии нет второго опроса, поэтому пробелы остаются пробелами. Мира не обязана давать полное техническое объяснение увиденному цвету, и отсутствие объяснения не разрешает исследователю придумать устройство панели. Вопрос проверяет наличие совместимых оснований, а не способность написать наиболее гладкий рассказ. По той же причине возможный проход Лады через другую дверь не включён в эталон. Такой маршрут мог бы примирить отдельные наблюдения, но в документах он не описан. Если модель предлагает его уверенно, это диагностический пример правдоподобной связи без доказательства. Корректная краткая формулировка сохраняет разногласие источников и указывает, что независимой записи для выбора между ними в переданном наборе нет.',
'Вера просила сохранить различие между незнанием автора и объективной неизвестностью для всех участников. Фраза о том, что ей не известны намерения, описывает её позицию. В досье также нет другого сообщения, раскрывающего эти намерения. Именно совместное отсутствие нужного основания делает вопрос неразрешимым в пределах набора. Если будущий документ скажет, что кто-то узнал намерения, но не сообщит их содержание, ответа на исходный вопрос всё ещё не появится. Это обстоятельство используется в подготовленном стресс-варианте: конфликт об осведомлённости не должен автоматически превращаться в уверенное обвинение. Аналогично знание личности скачавшего без её раскрытия не позволяет назвать Ладу. Для читателя важно проверять, какая именно пропозиция изменилась. Новое противоречие может быть реальным и при этом не давать требуемой информации по выбранному вопросу.',
'В аудиторском приложении отдельно обсуждается воспроизводимость. Для каждого ответа сохраняется текст реально переданного контекста. Это позволяет проверить, была ли нужная запись доступна генератору, и не путать ошибку поиска с ошибкой вывода. Пятнадцать строк поисковой выдачи фиксируются один раз; структурированный вариант переставляет именно их. Если бы организованная версия получала дополнительные строки журнала, сравнение формы потеряло бы смысл. Аналогично изменение порядка документов не должно незаметно менять их содержание. Аудитор рекомендует сопоставлять идентификаторы и контрольные значения файлов до запуска. Эти технические меры не гарантируют правильного ответа модели, но делают объяснение наблюдаемой ошибки проверяемым. В отчёте следует отдельно показать случаи отсутствующей посылки, неверной интерпретации доступного правила и отказа там, где основания были полными. Объединение всех случаев одним числом скрывает разные причины неудачи.',
'На полях репетиционного листа обсуждается сокращённый маршрут для опоздавших посетителей. Он касается навигации и не содержит разрешения обходить технические ограничения. Такие многозначные слова, как «доступ», «ключ» и «пуск», удобны в бытовой речи, но требуют осторожности при автоматическом поиске. В учебном архиве их смысл определяется окружающим абзацем. Если представить только отдельное слово, система потеряет различие между маршрутом в помещение и правом на публикацию. Поэтому в полном контексте оставлено описание назначения репетиции. В сокращённом реестре каждое утверждение также называет репетицию прямо. Это не исключает ошибочного извлечения, но позволяет генератору отвергнуть неподходящий фрагмент по видимому основанию. Исследование не предполагает, что вся нерелевантная информация выглядит бессмысленно: напротив, она должна быть понятной и правдоподобной в собственной ситуации, хотя не отвечает на вопрос о другом событии.',
'Черновик программы ещё не является отчётом о выполнении. Формы будущего времени сохранены намеренно. Они показывают план, а не подтверждённое действие. Даже если мероприятие в дальнейшем состоится, исследователь замороженного досье не знает его результатов. Это особенно важно для временной группировки: апрельские материалы относятся к периоду после мартовского инцидента, а не к его подготовке только потому, что стоят в общей папке. Ветвь контекста должна учитывать описываемое время, насколько оно известно, и не подменять его случайным местом файла в списке. Неизвестные точные моменты отмечаются отдельно. Внутри этой программы нет минутных отметок, пригодных для сравнения с журналом вечерней публикации. Попытка упорядочить их с выдуманной точностью создала бы дополнительные сведения, которых автор плана не сообщал. Для ответа достаточно сохранить грубую временную границу и нерелевантность документа.'
]
for i,x in enumerate(extra):items[i]+='\n\n'+x
p.write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding='utf8')
